import React from 'react';
import { motion, type HTMLMotionProps } from 'framer-motion';
import clsx from 'clsx';
import './AcidCard.css';

export interface AcidCardProps extends HTMLMotionProps<"div"> {
    variant?: 'flat' | 'outline' | 'dashed';
}

export const AcidCard = React.forwardRef<HTMLDivElement, AcidCardProps>(
    ({ className, variant = 'outline', children, ...props }, ref) => {
        return (
            <motion.div
                ref={ref}
                initial={{ opacity: 0, y: 10 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.3, ease: 'easeOut' }}
                className={clsx('ac-card', `ac-card-${variant}`, className)}
                {...props}
            >
                {children}
            </motion.div>
        );
    }
);

.ac-card {
    border-radius: var(--ac-radius-sm);
    padding: 1.5rem;
    overflow: hidden;
    position: relative;
    transition: border-color 0.2s ease, background 0.2s ease;
    background: var(--ac-surface);
}

/* Base Hover */
.ac-card:hover {
    border-color: var(--ac-text-muted);
}

/* Flat variant */
.ac-card-flat {
    border: 1px solid transparent;
}

.ac-card-flat:hover {
    background: var(--ac-surface-hover);
}

/* Outline variant */
.ac-card-outline {
    border: 1px solid var(--ac-border-muted);
}

.ac-card-outline:hover {
    border-color: var(--ac-text-secondary);
}

/* Dashed variant */
.ac-card-dashed {
    border: 1px dashed var(--ac-border-bright);
    background: transparent;
}

.ac-card-dashed:hover {
    border-color: var(--ac-text-primary);
    background: var(--ac-surface);
}
